graphql:
query InternetExposedEC2($projectId: String!, $first: Int, $after: String, $quick: Boolean) {
  graphSearch(
    projectId: $projectId, first: $first, after: $after, quick: $quick,
    query: {
      type: [VIRTUAL_MACHINE]
      select: true
      where: {
        cloudPlatform: { EQUALS: ["AWS"] }
        nativeType: { EQUALS: ["virtualMachine"] }
        accessibleFrom.internet: { EQUALS: true }
      }
    }
  ) {
    totalCount
    pageInfo { hasNextPage endCursor }
    nodes { entities { id name type properties } }
  }
}

query SecurityGroupsOpenToWorld($projectId: String!, $first: Int, $after: String, $quick: Boolean) {
  graphSearch(
    projectId: $projectId, first: $first, after: $after, quick: $quick,
    query: {
      type: [FIREWALL]
      select: true
      where: {
        cloudPlatform: { EQUALS: ["AWS"] }
        nativeType: { EQUALS: ["securityGroup"] }
      }
      relationships: [{
        type: [{ type: CONTAINS }]
        with: {
          type: [NETWORK_SECURITY_RULE]
          select: true
          where: { inbound: { EQUALS: true }, actionAllow: { EQUALS: true } }
          relationships: [{
            type: [{ type: CONTAINS_SRC_IP_RANGE }]
            with: { type: [IP_RANGE], where: { cidr: { EQUALS: ["0.0.0.0/0"] } } }
          }]
        }
      }]
    }
  ) {
    totalCount
    pageInfo { hasNextPage endCursor }
    nodes { entities { id name type properties } }
  }
}
